INSERT INTO questions (id, category_id, company_id, title, question_text, difficulty, question_type, topic, expected_answer, explanation) VALUES
(134, 2, NULL, 'Number Series - Increasing Differences', 'Find the next number in the series: 2, 6, 12, 20, 30, ?', 'EASY', 'MCQ', 'Number Series', '42', 'The differences are 4, 6, 8, 10, so the next difference is 12 and the next term is 30 + 12 = 42.'),
(135, 2, NULL, 'Number Series - Geometric Progression', 'Find the next number in the series: 3, 9, 27, 81, ?', 'EASY', 'MCQ', 'Number Series', '243', 'Each term is multiplied by 3: 81 x 3 = 243.'),
(136, 2, NULL, 'Number Series - Squares Plus One', 'Find the next number in the series: 2, 5, 10, 17, 26, ?', 'MEDIUM', 'MCQ', 'Number Series', '37', 'The terms follow n^2 + 1 (1+1, 4+1, 9+1, 16+1, 25+1). The next is 6^2 + 1 = 37.'),
(137, 2, NULL, 'Number Series - Double and Add One', 'Find the next number in the series: 5, 11, 23, 47, ?', 'MEDIUM', 'MCQ', 'Number Series', '95', 'Each term is twice the previous term plus 1: 47 x 2 + 1 = 95.'),
(138, 2, NULL, 'Number Series - Fibonacci Pattern', 'Find the missing number: 1, 1, 2, 3, 5, 8, ?, 21', 'EASY', 'MCQ', 'Number Series', '13', 'Each term is the sum of the two before it. 5 + 8 = 13, and 8 + 13 = 21 confirms it.'),
(139, 2, NULL, 'Number Series - Growing Differences', 'Find the next number in the series: 7, 10, 14, 19, 25, ?', 'MEDIUM', 'MCQ', 'Number Series', '32', 'The differences are 3, 4, 5, 6, so the next difference is 7: 25 + 7 = 32.'),
(140, 2, NULL, 'Number Series - Decreasing Differences', 'Find the next number in the series: 100, 95, 85, 70, 50, ?', 'MEDIUM', 'MCQ', 'Number Series', '25', 'The differences are -5, -10, -15, -20, so the next is -25: 50 - 25 = 25.'),
(141, 2, NULL, 'Syllogism - Chain of All Statements', 'Statements: All cats are dogs. All dogs are birds.
