INSERT INTO questions (id, category_id, company_id, title, question_text, difficulty, question_type, topic, expected_answer, explanation) VALUES
(159, 2, NULL, 'Antonym - Benevolent', 'Choose the word opposite in meaning to BENEVOLENT.', 'MEDIUM', 'MCQ', 'Antonyms', 'Malevolent', 'Benevolent means well-meaning and kind. Malevolent means wishing harm to others.'),
(160, 2, NULL, 'One Word - Lover of Books', 'Choose the single word for ''a person who loves books''.', 'EASY', 'MCQ', 'One-Word Substitution', 'Bibliophile', 'A bibliophile loves books. A philatelist collects stamps, a numismatist collects coins, and a misanthrope dislikes people.'),
(161, 2, NULL, 'Sentence Correction - Subject-Verb Agreement', 'Choose the grammatically correct sentence.', 'MEDIUM', 'MCQ', 'Sentence Correction', 'Neither of the students has submitted the assignment.', '''Neither'' is singular, so it takes the singular verb ''has'', and ''of the students'' needs the plural noun.'),
(162, 2, NULL, 'Fill in the Blank - Preposition', 'Fill in the blank: She is allergic ____ peanuts.', 'EASY', 'MCQ', 'Prepositions', 'to', 'The adjective ''allergic'' is followed by the preposition ''to''.'),
(163, 2, NULL, 'Idiom - Bite the Bullet', 'What does the idiom ''to bite the bullet'' mean?', 'MEDIUM', 'MCQ', 'Idioms', 'To face a painful or unpleasant situation bravely', 'It means to accept an unpleasant but unavoidable situation and deal with it with courage.'),
(164, 2, NULL, 'Reading Comprehension - Photosynthesis', 'Passage: ''Photosynthesis is the process by which green plants prepare food using sunlight, carbon dioxide and water. Oxygen is released as a by-product.''
