(209, 6, NULL, 'Content Delivery Network', 'What is the main purpose of a Content Delivery Network (CDN)?', 'MEDIUM', 'MCQ', 'CDN', 'To serve content from servers geographically close to users', 'Caching static assets at edge locations reduces latency and load on the origin server.'),
(210, 6, NULL, 'Role of a Router', 'Which device connects different networks and forwards packets between them using IP addresses?', 'EASY', 'MCQ', 'Network Devices', 'Router', 'Routers work at the network layer and choose the next hop for each packet using their routing tables.');
